using System.Collections;
using UnityEngine;

#if ENABLE_INPUT_SYSTEM
using UnityEngine.InputSystem;
#endif

[RequireComponent(typeof(AudioSource))]
public class BarIntro : MonoBehaviour
{
    public AudioClip welcomeVoice;

    private AudioSource voiceSource;
    private BarPlayerMovement movement;
    private UniformInteraction uniform;
    private BeerGlassPour beerInteraction;
    private GameObject musicRoot;
    private AudioSource musicSource;
    private AudioClip musicClip;
#if !UNITY_WEBGL || UNITY_EDITOR
    private UnityEngine.Networking.UnityWebRequest musicRequest;
#endif

    private bool started;
    private bool finished;

    public bool IsWaitingToStart => !started;

    void Awake()
    {
        uiCamera = GetComponentInChildren<Camera>();
        movement = GetComponent<BarPlayerMovement>();
        uniform = GetComponent<UniformInteraction>();
        voiceSource = GetComponent<AudioSource>();

        voiceSource.playOnAwake = false;
        voiceSource.loop = false;
        voiceSource.spatialBlend = 0f;
        voiceSource.Stop();

        if (movement == null || uniform == null)
        {
            Debug.LogError("BarIntro는 player에 붙여주세요.");
            enabled = false;
            return;
        }

        // 시작 대기 중에는 걷기만 막고 일인칭 시점은 계속 허용합니다.
        movement.enabled = true;
        uniform.enabled = false;

        Cursor.lockState = CursorLockMode.Locked;
        Cursor.visible = false;
        StartBackgroundMusic();
    }

    void StartBackgroundMusic()
    {
        beerInteraction = GetComponent<BeerGlassPour>();
        musicRoot = new GameObject("BackgroundMusic_Runtime");
        musicRoot.transform.SetParent(transform, false);
        musicSource = musicRoot.AddComponent<AudioSource>();
        musicSource.playOnAwake = false;
        musicSource.loop = true;
        musicSource.spatialBlend = 0f;
        musicSource.volume = 0.16f;
#if UNITY_WEBGL && !UNITY_EDITOR
        StartCoroutine(LoadWebBackgroundMusic());
#else
        StartCoroutine(LoadBackgroundMusic());
#endif
    }

#if !UNITY_WEBGL || UNITY_EDITOR
    string PrepareMusicCache()
    {
        try
        {
            string path = System.IO.Path.Combine(Application.temporaryCachePath, MusicCacheName);
            if (!System.IO.File.Exists(path) || new System.IO.FileInfo(path).Length != MusicByteCount)
            {
                byte[] data = System.Convert.FromBase64String(MusicOggBase64);
                System.IO.Directory.CreateDirectory(Application.temporaryCachePath);
                System.IO.File.WriteAllBytes(path, data);
            }
            return path;
        }
        catch (System.Exception exception)
        {
            Debug.LogWarning("Background music unavailable; gameplay will continue. " + exception.Message);
            return null;
        }
    }

    IEnumerator LoadBackgroundMusic()
    {
        string path = PrepareMusicCache();
        if (string.IsNullOrEmpty(path)) yield break;
        string audioUrl = new System.Uri(path).AbsoluteUri;
        // 양쪽 모두 포함된 음원을 사용하며 외부 서버에서 다운로드하지 않습니다.
        using (var request = UnityEngine.Networking.UnityWebRequestMultimedia.GetAudioClip(
            audioUrl, AudioType.OGGVORBIS))
        {
            musicRequest = request;
            try
            {
                request.timeout = 15;
#if !UNITY_WEBGL || UNITY_EDITOR
                ((UnityEngine.Networking.DownloadHandlerAudioClip)request.downloadHandler).streamAudio = true;
#endif
                yield return request.SendWebRequest();
                if (request.result != UnityEngine.Networking.UnityWebRequest.Result.Success)
                {
                    Debug.LogWarning("Background music could not be loaded. " + request.error);
                    yield break;
                }
                musicClip = UnityEngine.Networking.DownloadHandlerAudioClip.GetContent(request);
                if (musicSource == null || musicClip == null) yield break;
                musicClip.name = "Pour and Play";
                musicSource.clip = musicClip;
                musicSource.Play();
            }
            finally { musicRequest = null; }
        }
    }

#endif

#if UNITY_WEBGL && !UNITY_EDITOR
    IEnumerator LoadWebBackgroundMusic()
    {
        // 먼저 시작 화면을 그린 뒤 복원합니다. 데이터는 URL/외부 다운로드로 전달하지 않습니다.
        yield return null;
        WebMusicDecoder decoder = null;
        try { decoder = new WebMusicDecoder(); }
        catch (System.Exception exception)
        {
            Debug.LogWarning("Background music unavailable; gameplay will continue. " + exception.Message);
        }
        if (decoder == null) yield break;
        try
        {
            while (!decoder.IsComplete)
            {
                bool failed = false;
                try
                {
                    // 한 프레임에 제한된 블록만 복원해 화면과 시작 입력을 계속 처리합니다.
                    for (int block = 0; block < 32 && !decoder.IsComplete; block++) decoder.DecodeBlock();
                }
                catch (System.Exception exception)
                {
                    failed = true;
                    Debug.LogWarning("Background music unavailable; gameplay will continue. " + exception.Message);
                }
                if (failed) yield break;
                yield return null;
            }
            if (musicSource == null) yield break;
            try
            {
                musicClip = decoder.TakeClip();
                musicSource.clip = musicClip;
                musicSource.Play();
            }
            catch (System.Exception exception)
            {
                Debug.LogWarning("Background music unavailable; gameplay will continue. " + exception.Message);
            }
        }
        finally { decoder.Dispose(); }
    }

    // 표준 stereo WAV/IMA ADPCM 블록을 PCM으로 복원합니다. 브라우저 URI/코덱 지원에 의존하지 않습니다.
    private sealed class WebMusicDecoder : System.IDisposable
    {
        private readonly System.IO.Compression.GZipStream input;
        private readonly byte[] block;
        private readonly float[] samples;
        private float[] decoded;
        private readonly int blockSize, framesPerBlock;
        private int bytesRemaining, framesWritten;
        private AudioClip clip;
        private readonly int[] predictor = new int[MusicWebChannels];
        private readonly int[] stepIndex = new int[MusicWebChannels];
        private static readonly int[] IndexDelta = { -1, -1, -1, -1, 2, 4, 6, 8 };
        private static readonly int[] Steps = {
            7,8,9,10,11,12,13,14,16,17,19,21,23,25,28,31,34,37,41,45,50,55,60,66,73,80,
            88,97,107,118,130,143,157,173,190,209,230,253,279,307,337,371,408,449,494,544,
            598,658,724,796,876,963,1060,1166,1282,1411,1552,1707,1878,2066,2272,2499,
            2749,3024,3327,3660,4026,4428,4871,5358,5894,6484,7132,7845,8630,9493,
            10442,11487,12635,13899,15289,16818,18500,20350,22385,24623,27086,29794,32767
        };
        public bool IsComplete => framesWritten == MusicWebFrames;

        public WebMusicDecoder()
        {
            // 15비트씩 유효한 유니코드 문자에 보관합니다. 서로게이트/긴 URI/큰 base64 메타데이터를 피합니다.
            byte[] packed = new byte[MusicWebPackedBytes];
            if (MusicWebPacked15.Length != (packed.Length * 8 + 14) / 15)
                throw new System.IO.InvalidDataException("Music data length does not match.");
            int accumulator = 0, bits = 0, destination = 0;
            foreach (char character in MusicWebPacked15)
            {
                int value = character - 0x100;
                if (value < 0 || value > 32767) throw new System.IO.InvalidDataException("Invalid packed music character.");
                accumulator |= value << bits; bits += 15;
                while (bits >= 8 && destination < packed.Length)
                {
                    packed[destination++] = (byte)accumulator;
                    accumulator >>= 8; bits -= 8;
                }
            }
            input = new System.IO.Compression.GZipStream(new System.IO.MemoryStream(packed), System.IO.Compression.CompressionMode.Decompress);
            try
            {
                byte[] header = ReadBytes(12);
                if (!Tag(header, 0, "RIFF") || !Tag(header, 8, "WAVE")) throw new System.IO.InvalidDataException("Invalid music WAV header.");
                bool formatFound = false;
                while (true)
                {
                    byte[] chunk = ReadBytes(8);
                    int size = Read32(chunk, 4);
                    if (size < 0 || size > 8 * 1024 * 1024) throw new System.IO.InvalidDataException("Invalid music WAV chunk.");
                    if (Tag(chunk, 0, "data"))
                    {
                        if (!formatFound || size % blockSize != 0 || (long)(size / blockSize) * framesPerBlock < MusicWebFrames)
                            throw new System.IO.InvalidDataException("Music WAV data is incomplete.");
                        bytesRemaining = size;
                        break;
                    }
                    if (size > 4096) throw new System.IO.InvalidDataException("Unexpected music WAV metadata.");
                    byte[] data = ReadBytes(size);
                    if (Tag(chunk, 0, "fmt "))
                    {
                        if (data.Length < 20 || Read16(data, 0) != 17 || Read16(data, 2) != MusicWebChannels
                            || Read32(data, 4) != MusicWebRate || Read16(data, 14) != 4)
                            throw new System.IO.InvalidDataException("Unsupported music WAV format.");
                        blockSize = Read16(data, 12); framesPerBlock = Read16(data, 18);
                        if (blockSize < 16 || blockSize > 8192 || blockSize % 8 != 0
                            || framesPerBlock != 1 + (blockSize - MusicWebChannels * 4) * 2 / MusicWebChannels)
                            throw new System.IO.InvalidDataException("Invalid music ADPCM block size.");
                        formatFound = true;
                    }
                    if ((size & 1) != 0) ReadBytes(1);
                }
                block = new byte[blockSize]; samples = new float[framesPerBlock * MusicWebChannels];
                decoded = new float[MusicWebFrames * MusicWebChannels];
            }
            catch { Dispose(); throw; }
        }
        private static int Read16(byte[] data, int offset) { return data[offset] | data[offset + 1] << 8; }
        private static int Read32(byte[] data, int offset) { return Read16(data, offset) | Read16(data, offset + 2) << 16; }
        private static bool Tag(byte[] data, int offset, string tag)
        {
            for (int index = 0; index < 4; index++) if (data[offset + index] != tag[index]) return false;
            return true;
        }
        private void ReadExactly(byte[] data, int count)
        {
            int offset = 0;
            while (offset < count)
            {
                int read = input.Read(data, offset, count - offset);
                if (read == 0) throw new System.IO.EndOfStreamException("Music data ended unexpectedly.");
                offset += read;
            }
        }
        private byte[] ReadBytes(int count) { byte[] data = new byte[count]; ReadExactly(data, count); return data; }
        private float DecodeSample(int code, int channel)
        {
            int step = Steps[stepIndex[channel]];
            int delta = ((code & 7) * 2 + 1) * step >> 3;
            predictor[channel] = Mathf.Clamp(predictor[channel] + ((code & 8) != 0 ? -delta : delta), -32768, 32767);
            stepIndex[channel] = Mathf.Clamp(stepIndex[channel] + IndexDelta[code & 7], 0, 88);
            return predictor[channel] / 32768f;
        }
        public void DecodeBlock()
        {
            if (IsComplete) return;
            if (bytesRemaining < blockSize) throw new System.IO.EndOfStreamException("Missing music block.");
            ReadExactly(block, blockSize); bytesRemaining -= blockSize;
            for (int channel = 0; channel < MusicWebChannels; channel++)
            {
                predictor[channel] = unchecked((short)Read16(block, channel * 4));
                stepIndex[channel] = block[channel * 4 + 2];
                if (stepIndex[channel] > 88 || block[channel * 4 + 3] != 0) throw new System.IO.InvalidDataException("Invalid music predictor.");
                samples[channel] = predictor[channel] / 32768f;
            }
            int frame = 1;
            for (int offset = MusicWebChannels * 4; offset < blockSize; offset += MusicWebChannels * 4)
            {
                for (int channel = 0; channel < MusicWebChannels; channel++)
                    for (int index = 0; index < 4; index++)
                    {
                        int value = block[offset + channel * 4 + index];
                        samples[(frame + index * 2) * MusicWebChannels + channel] = DecodeSample(value & 15, channel);
                        samples[(frame + index * 2 + 1) * MusicWebChannels + channel] = DecodeSample(value >> 4, channel);
                    }
                frame += 8;
            }
            int count = Mathf.Min(framesPerBlock, MusicWebFrames - framesWritten);
            System.Array.Copy(samples, 0, decoded, framesWritten * MusicWebChannels, count * MusicWebChannels);
            framesWritten += count;
        }
        public AudioClip TakeClip()
        {
            if (!IsComplete) throw new System.IO.InvalidDataException("Background music is incomplete.");
            clip = AudioClip.Create("Pour and Play", MusicWebFrames, MusicWebChannels, MusicWebRate, false);
            // Web 버전 간 offsetSamples 지원 차이를 피하도록 전체 PCM을 한 번에 설정합니다.
            if (clip == null || !clip.SetData(decoded, 0)) throw new System.IO.InvalidDataException("Could not create background music clip.");
            AudioClip result = clip; clip = null; return result;
        }
        public void Dispose()
        {
            if (input != null) input.Dispose();
            if (clip != null) UnityEngine.Object.Destroy(clip);
            clip = null; decoded = null;
        }
    }
#endif

    void Update()
    {
        // 음악 로딩 여부와 관계없이 시작 입력은 처리합니다.
        if (!started && PressedStart()) StartCoroutine(PlayIntro());
        if (musicSource == null) return;
        bool speaking = (voiceSource != null && voiceSource.isPlaying)
            || (uniform != null && uniform.IsGuidePlaying)
            || (beerInteraction != null && beerInteraction.IsGuidePlaying);
        musicSource.volume = Mathf.MoveTowards(musicSource.volume, speaking ? 0.045f : 0.16f,
            Time.unscaledDeltaTime * 0.5f);
    }

    void OnDestroy()
    {
        if (introBoard != null) introBoard.Dispose();
#if !UNITY_WEBGL || UNITY_EDITOR
        if (musicRequest != null) musicRequest.Abort();
#endif
        if (musicSource != null) musicSource.Stop();
        if (musicRoot != null) Destroy(musicRoot);
        if (musicClip != null) Destroy(musicClip);
    }

    bool PressedStart()
    {
#if ENABLE_INPUT_SYSTEM
        return Keyboard.current != null && (Keyboard.current.enterKey.wasPressedThisFrame
            || Keyboard.current.numpadEnterKey.wasPressedThisFrame);
#else
        return Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter);
#endif
    }

    IEnumerator PlayIntro()
    {
        if (started) yield break;
        started = true;
        movement.enabled = true;
        Cursor.lockState = CursorLockMode.Locked;
        Cursor.visible = false;

        if (welcomeVoice != null && voiceSource.isActiveAndEnabled)
        {
            voiceSource.clip = welcomeVoice;
            voiceSource.Play();
        }

        // 재생이 시작된 다음 종료될 때까지 기다립니다.
        yield return null;

        while (voiceSource.isActiveAndEnabled && voiceSource.isPlaying)
            yield return null;

        finished = true;

        // 음성 종료 후 행위만 해제합니다. 이동/시점과 사용자의 커서 상태는 유지합니다.
        uniform.enabled = true;
    }

    private WorldPanel introBoard;
    private Camera uiCamera;
    void LateUpdate()
    {
        if (finished) { if (introBoard != null) introBoard.Hide(); return; }
        if (uiCamera == null) return;
        if (introBoard == null) introBoard = new WorldPanel(gameObject, "Entrance_WelcomeSign", 820f, 470f, 0.002f);
        SpatialLayout.BeginContext(uiCamera, "intro");
        introBoard.PoseAdaptive(uiCamera, SpatialSlot.Focus); introBoard.Begin();
        introBoard.Text(new Rect(24f, 24f, 772f, 88f), "HOW TO BE A BARTENDER", 43, WorldPanel.Accent, TextAnchor.MiddleCenter, true);
        introBoard.Text(new Rect(24f, 126f, 772f, 80f), started ? "Welcome to your first shift! Head inside the bar." : "Look around freely. The guide settles in view when you turn away.", 29, null, TextAnchor.MiddleCenter);
        // Enter starts the game; clicking to capture the WebGL pointer never starts it accidentally.
        introBoard.Fill(new Rect(90f, 227f, 640f, 110f), new Color(0.13f, 0.34f, 0.25f));
        introBoard.Text(new Rect(90f, 227f, 640f, 110f), started ? "LISTEN TO THE GUIDE" : "START / PRESS ENTER", 39, null, TextAnchor.MiddleCenter, true);
        introBoard.Text(new Rect(24f, 369f, 772f, 79f), started ? "You can move. Actions unlock after the voice ends." : "Click the game to capture the mouse. Press ENTER to start.\nWASD walking unlocks when you start.", 25, null, TextAnchor.MiddleCenter);
        introBoard.End();
    }
    void OnDisable() { if (introBoard != null) introBoard.Hide(); }

#if !UNITY_WEBGL || UNITY_EDITOR
    // 첨부 MP3 원본: Tools/AudioSources/PourAndPlay.mp3.
    // 전체 길이/스테레오를 유지한 Ogg를 포함해 기존 스크립트 동기화만으로 재생합니다.
    private const string MusicCacheName = "PourAndPlay-7227519d525423b5.ogg";
    private const int MusicByteCount = 1645441;
    private const string MusicOggBase64 = "";
#else
    // 동일한 음악 전체 길이/스테레오를 보존한 22.05 kHz IMA ADPCM. PCM 복원은 프레임별로 나눕니다.
    private const int MusicWebChannels = 2;
    private const int MusicWebRate = 22050;
    private const int MusicWebFrames = 3943422;
