    private const string MusicWebPacked15 = "\u0c1f\u0111\u0100\u0100\u3120\u6580\u206e\u0eba\u1b65\u315f\u6d95\u1390\u6a27\u1654\u2539\u25c9\u7640\u42c3\u05ec\u57dd\u53aa\u4fc4\u74d0\u2bc6\u4972\u3ec0\u6377\u4496\u7b06\u3ade\u6720\u75cc\u1aee\u0f73\u1948\u7977\u5071\u13dd\u1139\u3355\u2507\u5e0e\u2ba9\u0972\u023b\u2b3d\u0f1f\u41ec\u3299\u1655\u0225\u6df4\u568d\u0964\u3ae8\u1477\u6a96\u7c5f\u2fce\u6812\u4c9c\u7a86\u1107\u31cc\u6b9f\u1d37\u2806\u2cf0\u3ff5\u689f\u7aef\u79fb\u1a4a\u6172\u7ebe\u571e\u10dd\u42f9\u08c1\u7e0f\u40b3\u4df5\u2844\u4204\u4910\u4308\u1979\u4982\u09ff\u27fc\u3c7b\u5ef8\u5baf\u5afd\u4727\u543d\u7f1d\u60f6\u406f\u733f\u1f3f\u1c90\u06da\u40be\u80e0\u70b2\u201f\u5c90\u756f\u7946\u80fd\u45f8\u73ff\u77cf\u7e4c\u2fee\u4edf\u14ea\u4920\u2027\u4df1\u1127\u2bf0\u787f\u12df\u67c8\u23df\u4090\u38f3\u5e76\u38f2\u47fe\u67f0\u5f0a\u3ea4\u538b\u0f25\u6896\u68ac\u586b\u6046\u28da\u40d3\u1174\u1b5a\u19f1\u5e7c\u45e2\u67e4\u6451\u2681\u6451\u56e3\u74d6\u06d8\u7ede\u1eb7\u1d53\u6a7b\u3b3d\u3325\u5707\u05b3\u466d\u6ec8\u7b11\u1c4d\u2572\u10d5\u3021\u593e\u4e44\u637f\u6bb6\u3c0e\u55ba\u44c3\u710f\u4913\u0ded\u6362\u0b37\u507a\u5cdf\u5946\u4df7\u358c\u28bb\u2a05\u1078\u487a\u74f6\u7cd1\u74f4\u7383\u3404\u25b9\u07f1\u7a51\u3fde\u3238\u76b6\u6541\u4bcc\u14de\u4b8b\u64e3\u75a3\u47e3\u54c6\u4723\u7e6b\u7a85\u197b\u2ccd\u631f\u5b3a\u64fe\u742c\u2a81\u6c93\u3c45\u1c3a\u6d2b\u6b53\u0a32\u1855\u6ed2\u71f6\u5aff\u46bd\u78f0\u6b6d\u3f60\u339f\u026f\u3cf5\u0efd\u48e6\u3cf7\u102f\u0f88\u5ddc\u1a37\u3d75\u0a75\u05b1\u4bbb\u425e\u3f4e\u14b0\u32d5\u340b\u3cef\u5a4e\u7b9e\u35e6\u10ad\u295b\u6ce9\u5436\u4463\u4d27\u6449\u2673\u7e89\u0cab\u10ba\u5d5c\u05c2\u505e\u3c4c\u3a5f\u4950\u53b8\u14da\u467e\u455e\u145a\u3962\u28ac\u607b\u5ee3\u75ca\u2777\u452e\u5037\u488d\u1daf\u0b99\u3b3d\u67b0\u4b3a\u6bf4\u5bdb\u1abd\u2af8\u36e6\u56f7\u633e\u23dc\u74eb\u2f49\u7cea\u3d87\u5e7d\u25ae\u30bd\u5bfe\u21b4\u28e9\u367d\u160f\u5af9\u59ed\u59a9\u7fd9\u3627\u5e85\u7fdf\u54bb\u698b\u209f\u6f5d\u48ad\u708